window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-82ae53f2e77f8a56"]={"versions": [{"id": "FIG-82ae53f2e77f8a56", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR M2-Metamodell-Ausschnitt).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (Release R22-11), Spezifikation <code>AUTOSAR_TPS_ManifestSpecification</code>.</li>\n<li><strong>Funktionale Einordnung:</strong> Modellierung der Port-Schnittstellen für den Functional Cluster Persistency (<code>ara::per</code>). Das Metamodell definiert die deklarative Konfiguration für dateibasierten Speicher (<code>PersistencyFileStorageInterface</code>) zur Entkopplung der Applikationslogik von der physischen Dateisystem- und Speicherverwaltung (Flash, eMMC, NVRAM) sowie zur Festlegung von Redundanz- und Update-Strategien bei Software-Aktualisierungen via UCM (Update and Configuration Management).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen</p>\n<ul class=\"fig-list\">\n<li><strong><code>PersistencyInterface</code></strong> <em>(abstrakt, Package <code>PortInterface</code>)</em>:</li>\n<li>Basisklasse aller Persistenz-Schnittstellen (FileStorage und KeyValueStorage).</li>\n<li>Attribute:</li>\n<li><code>minimumSustainedSize: PositiveInteger [0..1]</code> – Garantiertes Speichervolumen in Bytes, das das System für diese Schnittstelle vorhalten muss.</li>\n<li><code>redundancy: PersistencyRedundancyEnum [0..1]</code> – Redundanzkonfiguration auf Speichergesamt-Ebene.</li>\n<li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum [0..1]</code> – Verhalten bei Software-Updates auf Ebene des Gesamtspeichers.</li>\n<li><strong><code>PersistencyFileStorageInterface</code></strong>:</li>\n<li>Konkrete Spezialisierung von <code>PersistencyInterface</code> (Generalisierungsbeziehung).</li>\n<li>Attribute:</li>\n<li><code>maxNumberOfFiles: PositiveInteger [0..1]</code> – Obergrenze der gleichzeitig verwaltbaren Dateien im File Storage.</li>\n<li>Assoziationen:</li>\n<li>Komposition <code>+fileElement: PersistencyFileElement [0..*]</code> – Aggregiert 0 bis $n$ vorab deklarierte Dateielemente.</li>\n<li><strong><code>PersistencyInterfaceElement</code></strong> <em>(abstrakt, Package <code>Identifiable</code>)</em>:</li>\n<li>Basisklasse für einzelne Elemente innerhalb einer Persistenz-Schnittstelle; erbt Identifizierbarkeit (<code>shortName</code>).</li>\n<li>Attribute:</li>\n<li><code>updateStrategy: PersistencyElementLevelUpdateStrategyEnum [0..1]</code> – Granulare Update-Strategie für das einzelne Element.</li>\n<li><strong><code>PersistencyFileElement</code></strong>:</li>\n<li>Spezialisierung von <code>PersistencyInterfaceElement</code> (Generalisierungsbeziehung).</li>\n<li>Repräsentiert eine konkrete, im Manifest definierte Datei.</li>\n<li>Attribute:</li>\n<li><code>contentUri: UriString [0..1]</code> – Pfad/URI zum initialen Dateiinhalt im Software-Paket.</li>\n<li><code>fileName: String [0..1]</code> – Logischer Dateiname innerhalb des Dateispeichers.</li>\n</ul>\n<p class=\"fig-p\">#### Enumerationen</p>\n<ul class=\"fig-list\">\n<li><strong><code>ComSpec::PersistencyRedundancyEnum</code></strong>:</li>\n<li><code>none</code> – Keine softwareseitige Redundanz.</li>\n<li><code>redundant</code> – Gesamter Speicher wird redundant/gespiegelt vorgehalten (z. B. M-out-of-N, Duplizierung).</li>\n<li><code>redundantPerElement</code> – Redundanz wird granular auf Dateiebene gesteuert.</li>\n<li><strong><code>PortInterface::PersistencyCollectionLevelUpdateStrategyEnum</code></strong>:</li>\n<li><code>keepExisting</code> – Bei Aktualisierung des Software-Clusters bleibt der bestehende Dateispeicher unverändert.</li>\n<li><code>delete</code> – Der gesamte Speicherbereich wird bei einem Update geleert/gelöscht.</li>\n<li><strong><code>PersistencyElementLevelUpdateStrategyEnum</code></strong>:</li>\n<li><code>overwrite</code> – Bestehende Zieldatei wird mit dem Stand aus <code>contentUri</code> überschrieben.</li>\n<li><code>keepExisting</code> – Existierende Zieldatei bleibt unberührt; fehlt sie, wird sie initial angelegt.</li>\n<li><code>delete</code> – Datei wird im Rahmen des Updates gezielt entfernt.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<p class=\"fig-p\">Als statisches M2-Strukturdiagramm bildet die Grafik keine Laufzeitsequenzen ab; das dynamische Verhalten manifestiert sich in zwei Phasen:</p>\n<ol class=\"fig-list\">\n<li><strong>Software-Update & Deployment (UCM-Verhalten):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Trigger:</strong> Aktivierung eines neuen Software-Cluster-Pakets via <code>ara::ucm</code>.</li>\n<li><strong>Evaluierungshierarchie:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Auswertung von <code>PersistencyInterface.updateStrategy</code>: Bei <code>delete</code> wird der physische Speicherordner komplett zurückgesetzt.</li>\n<li>Bei <code>keepExisting</code>: Iteration über alle <code>fileElement</code>-Instanzen. Ist für ein <code>PersistencyFileElement</code> eine <code>updateStrategy</code> definiert, überschreibt sie das Collection-Verhalten (<code>overwrite</code>, <code>keepExisting</code>, <code>delete</code>) und synchronisiert den Inhalt über <code>contentUri</code>.</li>\n<li><strong>Laufzeit-Zugriff (<code>ara::per</code>-Stack):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Applikation öffnet den Storage über <code>ara::per::OpenFileStorage(...)</code> via Port-Referenz.</li>\n<li>Der Persistency-Stack prüft Quotas (<code>maxNumberOfFiles</code>, <code>minimumSustainedSize</code>) gegen das Dateisystem und erzwingt bei I/O-Operationen transparent die konfigurierte Redundanz (<code>PersistencyRedundancyEnum</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurations- und Manifestbindung (TPS_MANI_01142, RS_MANI_00027):</strong></li>\n<li><code>PersistencyFileStorageInterface</code> dient als Typ für <code>PRPortPrototype</code>, <code>PPortPrototype</code> oder <code>RPortPrototype</code> im Application Design Manifest.</li>\n<li>Das Deployment-Mapping verknüpft dieses Interface mit physischen Speicherpfaden im Ausführungsmanifest (<code>PersistencyFileStorageDeployment</code>).</li>\n<li><strong>Ressourcenallokation & Quotas:</strong></li>\n<li><code>minimumSustainedSize</code> und <code>maxNumberOfFiles</code> sind bindende Vorgaben für Integratoren. Sie bestimmen Partitionsgrößen, POSIX-Quotas und Inode-Reservierungen im Zielbetriebssystem (z. B. QNX, Linux).</li>\n<li>Überschreitet eine Applikation zur Laufzeit <code>maxNumberOfFiles</code>, muss der Stack Operationen wie <code>OpenFileWrite()</code> mit dem Fehler <code>ara::per::PerErrc::kOutOfStorage</code> bzw. <code>kQuotaExceeded</code> ablehnen.</li>\n<li><strong>Integrität & ASIL-Anforderungen:</strong></li>\n<li>Ist <code>redundancy</code> auf <code>redundant</code> konfiguriert, implementiert der <code>ara::per</code>-Stack automatische Prüfsummen (CRC32/CRC64), Shadow-Files oder Block-Level-Replikation zur Erkennung und Behebung von Bitkippern/Flash-Degradation, ohne dass die Applikation eigene Redundanzlogik implementieren muss.</li>\n<li><strong>Release-Gültigkeit:</strong> Vollständig konform zu AUTOSAR Adaptive Platform R22-11.</li>\n</ul>"}, {"id": "FIG-36684de6efb79da7", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR M2-Metamodell-Ausschnitt).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (Release R22-11), Spezifikation <code>AUTOSAR_TPS_ManifestSpecification</code>.</li>\n<li><strong>Funktionale Einordnung:</strong> Modellierung der Port-Schnittstellen für den Functional Cluster Persistency (<code>ara::per</code>). Das Metamodell definiert die deklarative Konfiguration für dateibasierten Speicher (<code>PersistencyFileStorageInterface</code>) zur Entkopplung der Applikationslogik von der physischen Dateisystem- und Speicherverwaltung (Flash, eMMC, NVRAM) sowie zur Festlegung von Redundanz- und Update-Strategien bei Software-Aktualisierungen via UCM (Update and Configuration Management).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen</p>\n<ul class=\"fig-list\">\n<li><strong><code>PersistencyInterface</code></strong> <em>(abstrakt, Package <code>PortInterface</code>)</em>:</li>\n<li>Basisklasse aller Persistenz-Schnittstellen (FileStorage und KeyValueStorage).</li>\n<li>Attribute:</li>\n<li><code>contractVersion: StrongRevisionLabelString [0..1]</code> – Streng typisierte Versionsbezeichnung der Schnittstellenvereinbarung (Contract Versioning).</li>\n<li><code>minimumSustainedSize: PositiveInteger [0..1]</code> – Garantiertes Speichervolumen in Bytes, das das System für diese Schnittstelle vorhalten muss.</li>\n<li><code>redundancy: PersistencyRedundancyEnum [0..1]</code> – Redundanzkonfiguration auf Speichergesamt-Ebene.</li>\n<li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum [0..1]</code> – Verhalten bei Software-Updates auf Ebene des Gesamtspeichers.</li>\n<li><strong><code>PersistencyFileStorageInterface</code></strong>:</li>\n<li>Konkrete Spezialisierung von <code>PersistencyInterface</code> (Generalisierungsbeziehung).</li>\n<li>Attribute:</li>\n<li><code>maxNumberOfFiles: PositiveInteger [0..1]</code> – Obergrenze der gleichzeitig verwaltbaren Dateien im File Storage.</li>\n<li>Assoziationen:</li>\n<li>Komposition <code>+fileElement: PersistencyFileElement [0..*]</code> – Aggregiert 0 bis $n$ vorab deklarierte Dateielemente.</li>\n<li><strong><code>PersistencyInterfaceElement</code></strong> <em>(abstrakt, Package <code>Identifiable</code>)</em>:</li>\n<li>Basisklasse für einzelne Elemente innerhalb einer Persistenz-Schnittstelle; erbt Identifizierbarkeit (<code>shortName</code>).</li>\n<li>Attribute:</li>\n<li><code>updateStrategy: PersistencyElementLevelUpdateStrategyEnum [0..1]</code> – Granulare Update-Strategie für das einzelne Element.</li>\n<li><strong><code>PersistencyFileElement</code></strong>:</li>\n<li>Spezialisierung von <code>PersistencyInterfaceElement</code> (Generalisierungsbeziehung).</li>\n<li>Repräsentiert eine konkrete, im Manifest definierte Datei.</li>\n<li>Attribute:</li>\n<li><code>contentUri: UriString [0..1]</code> – Pfad/URI zum initialen Dateiinhalt im Software-Paket.</li>\n<li><code>fileName: String [0..1]</code> – Logischer Dateiname innerhalb des Dateispeichers.</li>\n</ul>\n<p class=\"fig-p\">#### Enumerationen</p>\n<ul class=\"fig-list\">\n<li><strong><code>PersistencyRedundancyEnum</code></strong>:</li>\n<li><code>none</code> – Keine softwareseitige Redundanz.</li>\n<li><code>redundant</code> – Gesamter Speicher wird redundant/gespiegelt vorgehalten (z. B. M-out-of-N, Duplizierung).</li>\n<li><code>redundantPerElement</code> – Redundanz wird granular auf Dateiebene gesteuert.</li>\n<li><strong><code>PersistencyCollectionLevelUpdateStrategyEnum</code></strong>:</li>\n<li><code>keepExisting</code> – Bei Aktualisierung des Software-Clusters bleibt der bestehende Dateispeicher unverändert.</li>\n<li><code>delete</code> – Der gesamte Speicherbereich wird bei einem Update geleert/gelöscht.</li>\n<li><strong><code>PersistencyElementLevelUpdateStrategyEnum</code></strong>:</li>\n<li><code>overwrite</code> – Bestehende Zieldatei wird mit dem Stand aus <code>contentUri</code> überschrieben.</li>\n<li><code>keepExisting</code> – Existierende Zieldatei bleibt unberührt; fehlt sie, wird sie initial angelegt.</li>\n<li><code>delete</code> – Datei wird im Rahmen des Updates gezielt entfernt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Strukturdiagramm bildet die Grafik keine Laufzeitsequenzen ab; das dynamische Verhalten manifestiert sich in zwei Phasen:</p>\n<ol class=\"fig-list\">\n<li><strong>Software-Update & Deployment (UCM-Verhalten):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Trigger:</strong> Aktivierung eines neuen Software-Cluster-Pakets via <code>ara::ucm</code>.</li>\n<li><strong>Evaluierungshierarchie:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Auswertung von <code>PersistencyInterface.updateStrategy</code>: Bei <code>delete</code> wird der physische Speicherordner komplett zurückgesetzt.</li>\n<li>Bei <code>keepExisting</code>: Iteration über alle <code>fileElement</code>-Instanzen. Ist für ein <code>PersistencyFileElement</code> eine <code>updateStrategy</code> definiert, überschreibt sie das Collection-Verhalten (<code>overwrite</code>, <code>keepExisting</code>, <code>delete</code>) und synchronisiert den Inhalt über <code>contentUri</code>.</li>\n<li><strong>Laufzeit-Zugriff (<code>ara::per</code>-Stack):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Applikation öffnet den Storage über <code>ara::per::OpenFileStorage(...)</code> via Port-Referenz.</li>\n<li>Der Persistency-Stack prüft Quotas (<code>maxNumberOfFiles</code>, <code>minimumSustainedSize</code>) gegen das Dateisystem und erzwingt bei I/O-Operationen transparent die konfigurierte Redundanz (<code>PersistencyRedundancyEnum</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurations- und Manifestbindung (TPS_MANI_01142, RS_MANI_00027):</strong></li>\n<li><code>PersistencyFileStorageInterface</code> dient als Typ für <code>PRPortPrototype</code>, <code>PPortPrototype</code> oder <code>RPortPrototype</code> im Application Design Manifest.</li>\n<li>Das Deployment-Mapping verknüpft dieses Interface mit physischen Speicherpfaden im Ausführungsmanifest (<code>PersistencyFileStorageDeployment</code>).</li>\n<li><strong>Schnittstellen-Versionierung (<code>contractVersion</code>):</strong></li>\n<li>Mit <code>contractVersion: StrongRevisionLabelString [0..1]</code> wird die formale Versionierung der Persistenz-Schnittstelle gemäß AUTOSAR-Revisionsetikett eingeführt. Integratoren und UCM können damit zur Entwurfs- und Update-Zeit prüfen, ob die Softwareversion einer Applikation mit dem Datenmodell und Speicherinhalt der Schnittstelle kompatibel ist.</li>\n<li><strong>Ressourcenallokation & Quotas:</strong></li>\n<li><code>minimumSustainedSize</code> und <code>maxNumberOfFiles</code> sind bindende Vorgaben für Integratoren. Sie bestimmen Partitionsgrößen, POSIX-Quotas und Inode-Reservierungen im Zielbetriebssystem (z. B. QNX, Linux).</li>\n<li>Überschreitet eine Applikation zur Laufzeit <code>maxNumberOfFiles</code>, muss der Stack Operationen wie <code>OpenFileWrite()</code> mit dem Fehler <code>ara::per::PerErrc::kOutOfStorage</code> bzw. <code>kQuotaExceeded</code> ablehnen.</li>\n<li><strong>Integrität & ASIL-Anforderungen:</strong></li>\n<li>Ist <code>redundancy</code> auf <code>redundant</code> konfiguriert, implementiert der <code>ara::per</code>-Stack automatische Prüfsummen (CRC32/CRC64), Shadow-Files oder Block-Level-Replikation zur Erkennung und Behebung von Bitkippern/Flash-Degradation, ohne dass die Applikation eigene Redundanzlogik implementieren muss.</li>\n<li><strong>Release-Gültigkeit:</strong> Vollständig konform zu AUTOSAR Adaptive Platform R23-11.</li>\n</ul>"}, {"id": "FIG-cfd87860b265c3c0", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR M2-Metamodell-Ausschnitt).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (Release R22-11), Spezifikation <code>AUTOSAR_TPS_ManifestSpecification</code>.</li>\n<li><strong>Funktionale Einordnung:</strong> Modellierung der Port-Schnittstellen für den Functional Cluster Persistency (<code>ara::per</code>). Das Metamodell definiert die deklarative Konfiguration für dateibasierten Speicher (<code>PersistencyFileStorageInterface</code>) zur Entkopplung der Applikationslogik von der physischen Dateisystem- und Speicherverwaltung (Flash, eMMC, NVRAM) sowie zur Festlegung von Redundanz- und Update-Strategien bei Software-Aktualisierungen via UCM (Update and Configuration Management).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen</p>\n<ul class=\"fig-list\">\n<li><strong><code>PersistencyInterface</code></strong> <em>(abstrakt, Package <code>PortInterface</code>)</em>:</li>\n<li>Basisklasse aller Persistenz-Schnittstellen (FileStorage und KeyValueStorage).</li>\n<li>Attribute:</li>\n<li><code>contractVersion: StrongRevisionLabelString [0..1]</code> – Streng typisierte Versionsbezeichnung der Schnittstellenvereinbarung (Contract Versioning).</li>\n<li><code>minimumSustainedSize: PositiveInteger [0..1]</code> – Garantiertes Speichervolumen in Bytes, das das System für diese Schnittstelle vorhalten muss.</li>\n<li><code>redundancy: PersistencyRedundancyEnum [0..1]</code> – Redundanzkonfiguration auf Speichergesamt-Ebene.</li>\n<li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum [0..1]</code> – Verhalten bei Software-Updates auf Ebene des Gesamtspeichers.</li>\n<li><strong><code>PersistencyFileStorageInterface</code></strong>:</li>\n<li>Konkrete Spezialisierung von <code>PersistencyInterface</code> (Generalisierungsbeziehung).</li>\n<li>Attribute:</li>\n<li><code>maxNumberOfFiles: PositiveInteger [0..1]</code> – Obergrenze der gleichzeitig verwaltbaren Dateien im File Storage.</li>\n<li>Assoziationen:</li>\n<li>Komposition <code>+fileElement: PersistencyFileElement [0..*]</code> – Aggregiert 0 bis $n$ vorab deklarierte Dateielemente.</li>\n<li><strong><code>PersistencyInterfaceElement</code></strong> <em>(abstrakt, Package <code>Identifiable</code>)</em>:</li>\n<li>Basisklasse für einzelne Elemente innerhalb einer Persistenz-Schnittstelle; erbt Identifizierbarkeit (<code>shortName</code>).</li>\n<li>Attribute:</li>\n<li><code>updateStrategy: PersistencyElementLevelUpdateStrategyEnum [0..1]</code> – Granulare Update-Strategie für das einzelne Element.</li>\n<li><strong><code>PersistencyFileElement</code></strong>:</li>\n<li>Spezialisierung von <code>PersistencyInterfaceElement</code> (Generalisierungsbeziehung).</li>\n<li>Repräsentiert eine konkrete, im Manifest definierte Datei.</li>\n<li>Attribute:</li>\n<li><code>contentUri: UriString [0..1]</code> – Pfad/URI zum initialen Dateiinhalt im Software-Paket.</li>\n<li><code>fileName: String [0..1]</code> – Logischer Dateiname innerhalb des Dateispeichers.</li>\n</ul>\n<p class=\"fig-p\">#### Enumerationen</p>\n<ul class=\"fig-list\">\n<li><strong><code>PersistencyRedundancyEnum</code></strong>:</li>\n<li><code>none</code> – Keine softwareseitige Redundanz.</li>\n<li><code>redundant</code> – Gesamter Speicher wird redundant/gespiegelt vorgehalten (z. B. M-out-of-N, Duplizierung).</li>\n<li><code>redundantPerElement</code> – Redundanz wird granular auf Dateiebene gesteuert.</li>\n<li><strong><code>PersistencyCollectionLevelUpdateStrategyEnum</code></strong>:</li>\n<li><code>keepExisting</code> – Bei Aktualisierung des Software-Clusters bleibt der bestehende Dateispeicher unverändert.</li>\n<li><code>delete</code> – Der gesamte Speicherbereich wird bei einem Update geleert/gelöscht.</li>\n<li><strong><code>PersistencyElementLevelUpdateStrategyEnum</code></strong>:</li>\n<li><code>overwrite</code> – Bestehende Zieldatei wird mit dem Stand aus <code>contentUri</code> überschrieben.</li>\n<li><code>keepExisting</code> – Existierende Zieldatei bleibt unberührt; fehlt sie, wird sie initial angelegt.</li>\n<li><code>delete</code> – Datei wird im Rahmen des Updates gezielt entfernt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Strukturdiagramm bildet die Grafik keine Laufzeitsequenzen ab; das dynamische Verhalten manifestiert sich in zwei Phasen:</p>\n<ol class=\"fig-list\">\n<li><strong>Software-Update & Deployment (UCM-Verhalten):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Trigger:</strong> Aktivierung eines neuen Software-Cluster-Pakets via <code>ara::ucm</code>.</li>\n<li><strong>Evaluierungshierarchie:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Auswertung von <code>PersistencyInterface.updateStrategy</code>: Bei <code>delete</code> wird der physische Speicherordner komplett zurückgesetzt.</li>\n<li>Bei <code>keepExisting</code>: Iteration über alle <code>fileElement</code>-Instanzen. Ist für ein <code>PersistencyFileElement</code> eine <code>updateStrategy</code> definiert, überschreibt sie das Collection-Verhalten (<code>overwrite</code>, <code>keepExisting</code>, <code>delete</code>) und synchronisiert den Inhalt über <code>contentUri</code>.</li>\n<li><strong>Laufzeit-Zugriff (<code>ara::per</code>-Stack):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Applikation öffnet den Storage über <code>ara::per::OpenFileStorage(...)</code> via Port-Referenz.</li>\n<li>Der Persistency-Stack prüft Quotas (<code>maxNumberOfFiles</code>, <code>minimumSustainedSize</code>) gegen das Dateisystem und erzwingt bei I/O-Operationen transparent die konfigurierte Redundanz (<code>PersistencyRedundancyEnum</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurations- und Manifestbindung (TPS_MANI_01142, RS_MANI_00027):</strong></li>\n<li><code>PersistencyFileStorageInterface</code> dient als Typ für <code>PRPortPrototype</code>, <code>PPortPrototype</code> oder <code>RPortPrototype</code> im Application Design Manifest.</li>\n<li>Das Deployment-Mapping verknüpft dieses Interface mit physischen Speicherpfaden im Ausführungsmanifest (<code>PersistencyFileStorageDeployment</code>).</li>\n<li><strong>Schnittstellen-Versionierung (<code>contractVersion</code>):</strong></li>\n<li>Mit <code>contractVersion: StrongRevisionLabelString [0..1]</code> wird die formale Versionierung der Persistenz-Schnittstelle gemäß AUTOSAR-Revisionsetikett eingeführt. Integratoren und UCM können damit zur Entwurfs- und Update-Zeit prüfen, ob die Softwareversion einer Applikation mit dem Datenmodell und Speicherinhalt der Schnittstelle kompatibel ist.</li>\n<li><strong>Ressourcenallokation & Quotas:</strong></li>\n<li><code>minimumSustainedSize</code> und <code>maxNumberOfFiles</code> sind bindende Vorgaben für Integratoren. Sie bestimmen Partitionsgrößen, POSIX-Quotas und Inode-Reservierungen im Zielbetriebssystem (z. B. QNX, Linux).</li>\n<li>Überschreitet eine Applikation zur Laufzeit <code>maxNumberOfFiles</code>, muss der Stack Operationen wie <code>OpenFileWrite()</code> mit dem Fehler <code>ara::per::PerErrc::kOutOfStorage</code> bzw. <code>kQuotaExceeded</code> ablehnen.</li>\n<li><strong>Integrität & ASIL-Anforderungen:</strong></li>\n<li>Ist <code>redundancy</code> auf <code>redundant</code> konfiguriert, implementiert der <code>ara::per</code>-Stack automatische Prüfsummen (CRC32/CRC64), Shadow-Files oder Block-Level-Replikation zur Erkennung und Behebung von Bitkippern/Flash-Degradation, ohne dass die Applikation eigene Redundanzlogik implementieren muss.</li>\n<li><strong>Release-Gültigkeit:</strong> Vollständig konform zu AUTOSAR Adaptive Platform R23-11.</li>\n</ul>"}, {"id": "FIG-2a50f6539c41b688", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR M2-Metamodell-Ausschnitt).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (Release R22-11), Spezifikation <code>AUTOSAR_TPS_ManifestSpecification</code>.</li>\n<li><strong>Funktionale Einordnung:</strong> Modellierung der Port-Schnittstellen für den Functional Cluster Persistency (<code>ara::per</code>). Das Metamodell definiert die deklarative Konfiguration für dateibasierten Speicher (<code>PersistencyFileStorageInterface</code>) zur Entkopplung der Applikationslogik von der physischen Dateisystem- und Speicherverwaltung (Flash, eMMC, NVRAM) sowie zur Festlegung von Redundanz- und Update-Strategien bei Software-Aktualisierungen via UCM (Update and Configuration Management).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen</p>\n<ul class=\"fig-list\">\n<li><strong><code>PersistencyInterface</code></strong> <em>(abstrakt, Package <code>PortInterface</code>)</em>:</li>\n<li>Basisklasse aller Persistenz-Schnittstellen (FileStorage und KeyValueStorage).</li>\n<li>Attribute:</li>\n<li><code>contractVersion: StrongRevisionLabelString [0..1]</code> – Streng typisierte Versionsbezeichnung der Schnittstellenvereinbarung (Contract Versioning).</li>\n<li><code>minimumSustainedSize: PositiveInteger [0..1]</code> – Garantiertes Speichervolumen in Bytes, das das System für diese Schnittstelle vorhalten muss.</li>\n<li><code>redundancy: PersistencyRedundancyEnum [0..1]</code> – Redundanzkonfiguration auf Speichergesamt-Ebene.</li>\n<li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum [0..1]</code> – Verhalten bei Software-Updates auf Ebene des Gesamtspeichers.</li>\n<li><strong><code>PersistencyFileStorageInterface</code></strong>:</li>\n<li>Konkrete Spezialisierung von <code>PersistencyInterface</code> (Generalisierungsbeziehung).</li>\n<li>Attribute:</li>\n<li><code>maxNumberOfFiles: PositiveInteger [0..1]</code> – Obergrenze der gleichzeitig verwaltbaren Dateien im File Storage.</li>\n<li>Assoziationen:</li>\n<li>Komposition <code>+fileElement: PersistencyFileElement [0..*]</code> – Aggregiert 0 bis $n$ vorab deklarierte Dateielemente.</li>\n<li><strong><code>PersistencyInterfaceElement</code></strong> <em>(abstrakt, Package <code>Identifiable</code>)</em>:</li>\n<li>Basisklasse für einzelne Elemente innerhalb einer Persistenz-Schnittstelle; erbt Identifizierbarkeit (<code>shortName</code>).</li>\n<li>Attribute:</li>\n<li><code>updateStrategy: PersistencyElementLevelUpdateStrategyEnum [0..1]</code> – Granulare Update-Strategie für das einzelne Element.</li>\n<li><strong><code>PersistencyFileElement</code></strong>:</li>\n<li>Spezialisierung von <code>PersistencyInterfaceElement</code> (Generalisierungsbeziehung).</li>\n<li>Repräsentiert eine konkrete, im Manifest definierte Datei.</li>\n<li>Attribute:</li>\n<li><code>contentUri: UriString [0..1]</code> – Pfad/URI zum initialen Dateiinhalt im Software-Paket.</li>\n<li><code>fileName: String [0..1]</code> – Logischer Dateiname innerhalb des Dateispeichers.</li>\n</ul>\n<p class=\"fig-p\">#### Enumerationen</p>\n<ul class=\"fig-list\">\n<li><strong><code>PersistencyRedundancyEnum</code></strong>:</li>\n<li><code>none</code> – Keine softwareseitige Redundanz.</li>\n<li><code>redundant</code> – Gesamter Speicher wird redundant/gespiegelt vorgehalten (z. B. M-out-of-N, Duplizierung).</li>\n<li><code>redundantPerElement</code> – Redundanz wird granular auf Dateiebene gesteuert.</li>\n<li><strong><code>PersistencyCollectionLevelUpdateStrategyEnum</code></strong>:</li>\n<li><code>keepExisting</code> – Bei Aktualisierung des Software-Clusters bleibt der bestehende Dateispeicher unverändert.</li>\n<li><code>delete</code> – Der gesamte Speicherbereich wird bei einem Update geleert/gelöscht.</li>\n<li><strong><code>PersistencyElementLevelUpdateStrategyEnum</code></strong>:</li>\n<li><code>overwrite</code> – Bestehende Zieldatei wird mit dem Stand aus <code>contentUri</code> überschrieben.</li>\n<li><code>keepExisting</code> – Existierende Zieldatei bleibt unberührt; fehlt sie, wird sie initial angelegt.</li>\n<li><code>delete</code> – Datei wird im Rahmen des Updates gezielt entfernt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Strukturdiagramm bildet die Grafik keine Laufzeitsequenzen ab; das dynamische Verhalten manifestiert sich in zwei Phasen:</p>\n<ol class=\"fig-list\">\n<li><strong>Software-Update & Deployment (UCM-Verhalten):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Trigger:</strong> Aktivierung eines neuen Software-Cluster-Pakets via <code>ara::ucm</code>.</li>\n<li><strong>Evaluierungshierarchie:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Auswertung von <code>PersistencyInterface.updateStrategy</code>: Bei <code>delete</code> wird der physische Speicherordner komplett zurückgesetzt.</li>\n<li>Bei <code>keepExisting</code>: Iteration über alle <code>fileElement</code>-Instanzen. Ist für ein <code>PersistencyFileElement</code> eine <code>updateStrategy</code> definiert, überschreibt sie das Collection-Verhalten (<code>overwrite</code>, <code>keepExisting</code>, <code>delete</code>) und synchronisiert den Inhalt über <code>contentUri</code>.</li>\n<li><strong>Laufzeit-Zugriff (<code>ara::per</code>-Stack):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Applikation öffnet den Storage über <code>ara::per::OpenFileStorage(...)</code> via Port-Referenz.</li>\n<li>Der Persistency-Stack prüft Quotas (<code>maxNumberOfFiles</code>, <code>minimumSustainedSize</code>) gegen das Dateisystem und erzwingt bei I/O-Operationen transparent die konfigurierte Redundanz (<code>PersistencyRedundancyEnum</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurations- und Manifestbindung (TPS_MANI_01142, RS_MANI_00027):</strong></li>\n<li><code>PersistencyFileStorageInterface</code> dient als Typ für <code>PRPortPrototype</code>, <code>PPortPrototype</code> oder <code>RPortPrototype</code> im Application Design Manifest.</li>\n<li>Das Deployment-Mapping verknüpft dieses Interface mit physischen Speicherpfaden im Ausführungsmanifest (<code>PersistencyFileStorageDeployment</code>).</li>\n<li><strong>Schnittstellen-Versionierung (<code>contractVersion</code>):</strong></li>\n<li>Mit <code>contractVersion: StrongRevisionLabelString [0..1]</code> wird die formale Versionierung der Persistenz-Schnittstelle gemäß AUTOSAR-Revisionsetikett eingeführt. Integratoren und UCM können damit zur Entwurfs- und Update-Zeit prüfen, ob die Softwareversion einer Applikation mit dem Datenmodell und Speicherinhalt der Schnittstelle kompatibel ist.</li>\n<li><strong>Ressourcenallokation & Quotas:</strong></li>\n<li><code>minimumSustainedSize</code> und <code>maxNumberOfFiles</code> sind bindende Vorgaben für Integratoren. Sie bestimmen Partitionsgrößen, POSIX-Quotas und Inode-Reservierungen im Zielbetriebssystem (z. B. QNX, Linux).</li>\n<li>Überschreitet eine Applikation zur Laufzeit <code>maxNumberOfFiles</code>, muss der Stack Operationen wie <code>OpenFileWrite()</code> mit dem Fehler <code>ara::per::PerErrc::kOutOfStorage</code> bzw. <code>kQuotaExceeded</code> ablehnen.</li>\n<li><strong>Integrität & ASIL-Anforderungen:</strong></li>\n<li>Ist <code>redundancy</code> auf <code>redundant</code> konfiguriert, implementiert der <code>ara::per</code>-Stack automatische Prüfsummen (CRC32/CRC64), Shadow-Files oder Block-Level-Replikation zur Erkennung und Behebung von Bitkippern/Flash-Degradation, ohne dass die Applikation eigene Redundanzlogik implementieren muss.</li>\n<li><strong>Release-Gültigkeit:</strong> Vollständig konform zu AUTOSAR Adaptive Platform R23-11.</li>\n</ul>"}], "trans": [{"from": "FIG-82ae53f2e77f8a56", "to": "FIG-36684de6efb79da7", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>PersistencyInterface</code>: Neues Attribut <code>+ contractVersion: StrongRevisionLabelString [0..1]</code> ergänzt.</li>\n<li><code>PersistencyRedundancyEnum</code>: Paket-Präfix <code>ComSpec::</code> im Namen der Enumeration entfernt.</li>\n<li><code>PersistencyCollectionLevelUpdateStrategyEnum</code>: Paket-Präfix <code>PortInterface::</code> im Namen der Enumeration entfernt.</li>\n</ul>"}, {"from": "FIG-36684de6efb79da7", "to": "FIG-cfd87860b265c3c0", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>PersistencyRedundancyEnum</code>: UML-Kompartiment-Kennzeichnung <em>literals</em> oberhalb der Aufzählungswerte ergänzt.</li>\n<li><code>PersistencyCollectionLevelUpdateStrategyEnum</code>: UML-Kompartiment-Kennzeichnung <em>literals</em> oberhalb der Aufzählungswerte ergänzt.</li>\n<li><code>PersistencyElementLevelUpdateStrategyEnum</code>: UML-Kompartiment-Kennzeichnung <em>literals</em> oberhalb der Aufzählungswerte ergänzt.</li>\n</ul>"}, {"from": "FIG-cfd87860b265c3c0", "to": "FIG-2a50f6539c41b688", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
